            q=deque([(r,c)]); seen.add((r,c)); pts=[]
            while q:
                y,x=q.popleft(); pts.append((y,x))
                for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0,r1=min(y for y,x in pts),max(y for y,x in pts)
            c0,c1=min(x for y,x in pts),max(x for y,x in pts)
            # A closed shape encloses at least one zero region not connected to exterior.
            enclosed=[]; visited=set()
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if grid[y][x]!=0 or (y,x) in visited: continue
                    qq=deque([(y,x)]); visited.add((y,x)); region=[]; leaks=False
                    while qq:
                        yy,xx=qq.popleft(); region.append((yy,xx))
                        if yy in (r0,r1) or xx in (c0,c1): leaks=True
                        for y2,x2 in ((yy+1,xx),(yy-1,xx),(yy,xx+1),(yy,xx-1)):
                            if r0<=y2<=r1 and c0<=x2<=c1 and grid[y2][x2]==0 and (y2,x2) not in visited:
                                visited.add((y2,x2)); qq.append((y2,x2))
                    if not leaks: enclosed.extend(region)
            if not enclosed: continue
            for y,x in enclosed: out[y][x]=3
